int main(void){
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    int *a = (int*)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    /* insertion sort */
    for (int i = 1; i < n; i++){
        int key = a[i], j = i - 1;
        while (j >= 0 && a[j] > key){ a[j+1] = a[j]; j--; }
        a[j+1] = key;
    }
    int threshold = n / k, first = 1, i = 0;
    while (i < n){
        int j = i;
        while (j < n && a[j] == a[i]) j++;
        if (j - i > threshold){
            if (!first) putchar(' ');
            printf("%d", a[i]); first = 0;
        }
        i = j;
    }
    putchar('\n');
    free(a);
    return 0;
}

