typedef struct Node { int data; struct Node *left, *right; } Node;
static Node* insert(Node *t, int v){
    if (!t){ Node *p = (Node*)malloc(sizeof(Node)); p->data = v; p->left = p->right = NULL; return p; }
    if (v < t->data) t->left = insert(t->left, v);
    else if (v > t->data) t->right = insert(t->right, v);
    return t;
}
static int k, ans;
static void inorder(Node *t){
    if (!t || k <= 0) return;
    inorder(t->left);
    if (--k == 0){ ans = t->data; return; }
    inorder(t->right);
}
int main(void){
    int n;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    Node *root = NULL;
    for (int i = 0; i < n; i++){ int v; scanf("%d", &v); root = insert(root, v); }
    inorder(root);
    printf("%d\n", ans);
    return 0;
}

