int a[100005], n;
static int sym(int i, int j){
    int li = (i < n && a[i] != -1), lj = (j < n && a[j] != -1);
    if (!li && !lj) return 1;
    if (!li || !lj) return 0;
    if (a[i] != a[j]) return 0;
