#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *left, *right; } Node;
static Node* ins(Node *t, int v){
    if (!t){ Node *p = (Node*)malloc(sizeof(Node)); p->data = v; p->left = p->right = NULL; return p; }
    if (v < t->data) t->left = ins(t->left, v);
    else if (v > t->data) t->right = ins(t->right, v);
    return t;
}
static Node* del(Node *t, int v){
    if (!t) return NULL;
    if (v < t->data) t->left = del(t->left, v);
    else if (v > t->data) t->right = del(t->right, v);
    else {
        if (!t->left) return t->right;
        if (!t->right) return t->left;
        Node *s = t->right;
        while (s->left) s = s->left;
        t->data = s->data;
        t->right = del(t->right, s->data);
    }
    return t;
}
static int first;
static void inord(Node *t){
    if (!t) return;
    inord(t->left);
    if (!first) putchar(' ');
    printf("%d", t->data); first = 0;
    inord(t->right);
}
int main(void){
    int n, x;
    if (scanf("%d %d", &n, &x) != 2) return 0;
    Node *root = NULL;
    for (int i = 0; i < n; i++){ int v; scanf("%d", &v); root = ins(root, v); }
    root = del(root, x);
    first = 1;
    inord(root);
    putchar('\n');
    return 0;
}

