#include <stdio.h>
#include <string.h>

int adj[105][105];
int parent[105];
int find(int x){ while (parent[x] != x){ parent[x] = parent[parent[x]]; x = parent[x]; } return x; }

int n;
int components(int exclude){
    for (int i = 0; i < n; i++) parent[i] = i;
    for (int u = 0; u < n; u++){
        if (u == exclude) continue;
        for (int v = u + 1; v < n; v++)
            if (v != exclude && adj[u][v]) parent[find(u)] = find(v);
    }
    int cnt = 0;
    for (int i = 0; i < n; i++)
        if (i != exclude && find(i) == i) cnt++;
    return cnt;
}

int main(void){
    int m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    memset(adj, 0, sizeof(adj));
    for (int i = 0; i < m; i++){
        int u, v; scanf("%d %d", &u, &v);
        adj[u][v] = adj[v][u] = 1;
    }
    int base = components(-1);
    int cuts[105], k = 0;
    for (int v = 0; v < n; v++)
        if (components(v) > base) cuts[k++] = v;
    printf("%d\n", k);
    for (int i = 0; i < k; i++){ if (i) putchar(' '); printf("%d", cuts[i]); }
    putchar('\n');
    return 0;
}

