    int table[105];
    memset(table, -1, sizeof(table));
    for (int i = 0; i < n; i++){
        int k; scanf("%d", &k);
        int h = k % m;
        while (table[h] != -1) h = (h + 1) % m;
        table[h] = k;
    }
    int first = 1;
    for (int i = 0; i < q; i++){
        int k; scanf("%d", &k);
        int h = k % m, pos = -1;
