            if (table[h] == -1) break;
            if (table[h] == k){ pos = h; break; }
            h = (h + 1) % m;
        }
        if (!first) putchar(' ');
        printf("%d", pos); first = 0;
    }
    putchar('\n');
    return 0;
}
